//! The two instruction sets, each generated by `define_ops!` from its opcode list:
//!
//! - [`full`]: the full set the lowering emits, from `full_ops.rs`, the single opcode list.
//! - [`reduced`]: the reduced set that runs as native code, from `reduced_ops.rs` (generated
//!   from `full_ops.rs` by `vm/bytecode/tests/reduced.rs`). It reuses [`full`]'s operand
//!   machinery, hence `full`'s `#[macro_use]`.
//!
//! The crate root re-exports both, so their paths are `crate::full` and `crate::reduced`.

#[macro_use]
pub mod full;
pub mod reduced;
